func:
// ─────────────────────────────────────────────────────────────────────
//  SecureDrop gateway settings. Fill these in, then press Deploy.
//  Leave a token empty to switch that integration off (the rest still runs).
// ─────────────────────────────────────────────────────────────────────
const cfg = {
    // Telegram: create a bot with @BotFather, paste its token here.
    telegramToken: "",
    // Your chat id: send any message to the bot, then open
    // https://api.telegram.org/bot<TOKEN>/getUpdates and copy chat.id
    telegramChatId: "",

    // Blynk IoT: Device -> Device Info -> Auth Token
    blynkToken: "",
    blynkCountPin: "V0",   // Integer datastream: total deliveries
    blynkTimePin:  "V1",   // String datastream: time of last delivery

    archiveDir: "archive", // folder (next to flows.json) where photos are kept
    keep: 50               // deliveries shown on the log page
};

// Environment variables override the values above (keeps tokens out of the file).
cfg.telegramToken  = env.get("SD_TELEGRAM_TOKEN")   || cfg.telegramToken;
cfg.telegramChatId = env.get("SD_TELEGRAM_CHAT_ID") || cfg.telegramChatId;
cfg.blynkToken     = env.get("SD_BLYNK_TOKEN")      || cfg.blynkToken;
cfg.telegramBase   = env.get("SD_TELEGRAM_BASE")    || "https://api.telegram.org";
cfg.blynkBase      = env.get("SD_BLYNK_BASE")       || "https://blynk.cloud";

flow.set("cfg", cfg);
const on = [];
if (cfg.telegramToken && cfg.telegramChatId) on.push("Telegram");
if (cfg.blynkToken) on.push("Blynk");
node.status({ fill: on.length ? "green" : "grey", shape: "dot",
              text: "archive" + (on.length ? " + " + on.join(" + ") : " only") });
return null;

// The firmware publishes a small JSON event just before the image.
// Keep it so the image handler can attach device details to the photo.
const e = (msg.payload && typeof msg.payload === "object") ? msg.payload : {};
flow.set("lastEvent", { at: Date.now(), data: e });
node.status({ fill: "blue", shape: "dot", text: (e.device || "unknown") + " woke (" + (e.wake || "?") + ")" });
return msg;

// One image = one delivery. Build the record, then fan out to
// archive / Telegram / Blynk (each wire gets its own copy of msg).
const cfg = flow.get("cfg") || { archiveDir: "archive", keep: 50 };
const img = msg.payload;

// A JPEG always starts with FF D8. Drop anything else (truncated or junk payload).
if (!Buffer.isBuffer(img) || img.length < 4 || img[0] !== 0xFF || img[1] !== 0xD8) {
    node.status({ fill: "red", shape: "ring", text: "rejected: not a JPEG" });
    node.warn("securedrop/image payload is not a JPEG, ignored");
    return null;
}

const now = new Date();
const p = (n) => String(n).padStart(2, "0");
const date = now.getFullYear() + "-" + p(now.getMonth() + 1) + "-" + p(now.getDate());
const time = p(now.getHours()) + ":" + p(now.getMinutes()) + ":" + p(now.getSeconds());

// Use the event only if it arrived in the last 15 s (i.e. it belongs to this wake).
const last = flow.get("lastEvent");
const ev = (last && now.getTime() - last.at < 15000) ? last.data : {};

const count = (flow.get("count") || 0) + 1;
flow.set("count", count);

const file = "delivery_" + date + "_" + time.replace(/:/g, "-") + "_" + String(count).padStart(4, "0") + ".jpg";
const record = {
    id: count,
    time: date + " " + time,
    file: file,
    bytes: img.length,
    device: String(ev.device || "unknown").slice(0, 40),
    wake: String(ev.wake || "?").slice(0, 20),
    rssi: (typeof ev.rssi === "number") ? ev.rssi : null,
    archived: false,
    telegram: (cfg.telegramToken && cfg.telegramChatId) ? "pending" : "off",
    blynk: cfg.blynkToken ? "pending" : "off"
};

const list = flow.get("deliveries") || [];
list.unshift(record);
flow.set("deliveries", list.slice(0, cfg.keep || 50));

msg.record = record;
msg.filename = cfg.archiveDir + "/" + file;
node.status({ fill: "green", shape: "dot", text: "#" + count + "  " + time + "  " + Math.round(img.length / 1024) + " kB" });
return msg;

const list = flow.get("deliveries") || [];
const r = list.find(d => d.id === msg.record.id);
if (r) { r.archived = true; flow.set("deliveries", list); }
node.status({ fill: "green", shape: "dot", text: msg.record.file });
return null;

// Telegram Bot API: POST /bot<token>/sendPhoto as multipart/form-data.
const cfg = flow.get("cfg") || {};
if (!cfg.telegramToken || !cfg.telegramChatId) {
    node.status({ fill: "grey", shape: "ring", text: "off (no token in CONFIG)" });
    return null;
}
const r = msg.record;
msg.branch = "telegram";
msg.method = "POST";
msg.url = cfg.telegramBase + "/bot" + cfg.telegramToken + "/sendPhoto";
msg.headers = { "content-type": "multipart/form-data" };
msg.payload = {
    chat_id: String(cfg.telegramChatId),
    caption: "SecureDrop: parcel delivered\n" + r.time + "\nDevice: " + r.device + "  |  Delivery #" + r.id,
    photo: { value: msg.payload, options: { filename: r.file, contentType: "image/jpeg" } }
};
node.status({ fill: "blue", shape: "dot", text: "sending #" + r.id });
return msg;

const ok = msg.statusCode === 200 && msg.payload && msg.payload.ok === true;
const list = flow.get("deliveries") || [];
const r = list.find(d => d.id === msg.record.id);
if (r) { r.telegram = ok ? "sent" : "failed"; flow.set("deliveries", list); }
node.status({ fill: ok ? "green" : "red", shape: "dot", text: ok ? "sent #" + msg.record.id : "failed (HTTP " + msg.statusCode + ")" });
msg.payload = { telegram: ok ? "sent" : "failed", status: msg.statusCode,
                detail: ok ? undefined : (msg.payload && msg.payload.description) };
delete msg.url; delete msg.headers;   // never show the bot token in the debug pane
return msg;

// Blynk HTTPS API: GET /external/api/batch/update?token=...&V0=...&V1=...
const cfg = flow.get("cfg") || {};
if (!cfg.blynkToken) {
    node.status({ fill: "grey", shape: "ring", text: "off (no token in CONFIG)" });
    return null;
}
const r = msg.record;
msg.branch = "blynk";
msg.method = "GET";
msg.url = cfg.blynkBase + "/external/api/batch/update"
        + "?token=" + encodeURIComponent(cfg.blynkToken)
        + "&" + cfg.blynkCountPin + "=" + r.id
        + "&" + cfg.blynkTimePin + "=" + encodeURIComponent(r.time);
msg.payload = "";
msg.headers = {};
node.status({ fill: "blue", shape: "dot", text: "updating" });
return msg;

const ok = msg.statusCode === 200;
const list = flow.get("deliveries") || [];
const r = list.find(d => d.id === msg.record.id);
if (r) { r.blynk = ok ? "updated" : "failed"; flow.set("deliveries", list); }
node.status({ fill: ok ? "green" : "red", shape: "dot", text: ok ? "updated #" + msg.record.id : "failed (HTTP " + msg.statusCode + ")" });
msg.payload = { blynk: ok ? "updated" : "failed", status: msg.statusCode };
delete msg.url; delete msg.headers;   // never show the auth token in the debug pane
return msg;

// No internet / DNS failure etc. The photo is already archived; just record the miss.
const list = flow.get("deliveries") || [];
const r = msg.record && list.find(d => d.id === msg.record.id);
if (r && msg.branch) { r[msg.branch] = "failed"; flow.set("deliveries", list); }
msg.payload = { [msg.branch || "notify"]: "failed", detail: msg.error && msg.error.message };
delete msg.url; delete msg.headers;
return msg;

const cfg = flow.get("cfg") || {};
msg.payload = {
    count: flow.get("count") || 0,
    telegram: !!(cfg.telegramToken && cfg.telegramChatId),
    blynk: !!cfg.blynkToken,
    deliveries: flow.get("deliveries") || []
};
msg.headers = { "content-type": "application/json", "cache-control": "no-store" };
return msg;

// Only serve files this gateway wrote (blocks ../ style paths).
const cfg = flow.get("cfg") || { archiveDir: "archive" };
const name = String(msg.req.params.name || "");
if (!/^delivery_[0-9_-]+\.jpg$/.test(name)) {
    msg.statusCode = 404; msg.payload = "not found";
    return [null, msg];
}
msg.filename = cfg.archiveDir + "/" + name;
return [msg, null];

// SIMULATOR ONLY. Publishes exactly what the ESP32-CAM firmware publishes:
// a JSON event on securedrop/event, then the JPEG bytes on securedrop/image.
// Both go through the real broker, so sections 2 and 3 run unchanged.
const img = msg.payload;
if (!Buffer.isBuffer(img) || img.length < 4) {
    msg.statusCode = 400; msg.payload = { ok: false, error: "send JPEG bytes as application/octet-stream" };
    return [null, msg];
}
const n = (context.get("boot") || 0) + 1;
context.set("boot", n);
const evt = { topic: "securedrop/event",
              payload: JSON.stringify({ device: "simulator", event: "delivery", wake: "button", bytes: img.length, boot: n }) };
const pic = { topic: "securedrop/image", payload: img };
msg.payload = { ok: true, bytes: img.length };
return [[evt, pic], msg];
